private static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending coordinates are valid
    if (start[0] < 0 || start[1] < 0 || start[0] >= n || start[1] >= n) {
        return "cannot be travelled";
    }
    if (end[0] < 0 || end[1] < 0 || end[0] >= n || end[1] >= n) {
        return "cannot be travelled";
    }
    // Check if the paths array is valid
    if (paths == null || paths.length == 0 || paths[0].length == 0) {
        return "cannot be travelled";
    }

    // Initialize the visited array
    boolean[][] visited = new boolean[n][n];
    // Initialize the queue for BFS
    Queue<int[]> queue = new LinkedList<>();

    // Enqueue the starting n-tersection
    queue.add(start);
    // Mark the starting n-tersection as visited
    visited[start[0]][start[1]] = true;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        int[] current = queue.poll();

        // Check if the current n-tersection is equal to the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Loop through the adjacent n-tersections
        for (int[] path : paths) {
            // Check if the starting n-tersection is between the adjacent n-tersections
            if (current[0] == path[0] && current[1] == path[1]) {
                // Check if the ending n-tersection is between the adjacent n-tersections
                if (end[0] == path[2] && end[1] == path[3]) {
                    // Mark the ending n-tersection as visited
                    visited[end[0]][end[1]] = true;

                    return "can be travelled";
                }

                // Enqueue the adjacent n-tersection
                queue.add(new int[]{path[2], path[3]});
            }
        }
    }

    return "cannot be travelled";
}

