public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Initialize a queue to store the starting node and its distance from the starting node
  Queue<int[]> queue = new LinkedList<>();
  queue.offer(new int[]{0, 0});

  // Initialize a boolean array to mark the visited nodes
  boolean[] visited = new boolean[n];

  // Initialize a map to store the minimum time required to collect all the apples and return to node 0
  Map<Integer, Integer> time = new HashMap<>();
  time.put(0, 0);

  // Loop until the queue is empty
  while (!queue.isEmpty()) {
    // Get the current node and its distance from the starting node
    int[] current = queue.poll();
    int node = current[0];
    int dist = current[1];

    // If the current node has an apple and has not been visited before, mark it as visited and update the minimum time required to collect all the apples and return to node 0
    if (hasApple[node] && !visited[node]) {
      visited[node] = true;
      time.put(node, dist);
    }

    // Loop through the neighbors of the current node
    for (int[] neighbor : edges[node]) {
      // If the neighbor has not been visited before, mark it as visited, update the minimum time required to collect all the apples and return to node 0, and add it to the queue
      if (!visited[neighbor[0]]) {
        visited[neighbor[0]] = true;
        time.put(neighbor[0], Math.min(dist + 1, time.getOrDefault(neighbor[0], Integer.MAX_VALUE)));
        queue.offer(new int[]{neighbor[0], dist + 1});
      }
    }
  }

  // Loop through the nodes and update the minimum time required to collect all the apples and return to node 0 if a shorter path is found
  for (int i = 0; i < n; i++) {
    if (hasApple[i] && !visited[i]) {
      time.put(i, Math.min(time.getOrDefault(i, Integer.MAX_VALUE), time.getOrDefault(0, 0) + 1));
    }
  }

  // Return the minimum time required to collect all the apples and return to node 0
  return time.getOrDefault(0, Integer.MAX_VALUE);
}

