public int minCostClimbingStairs(int[] cost) {
    // Base case: if cost array has only one element, return its value
    if (cost.length == 1) return cost[0];

    // Set to store solutions for subproblems
    Set<Integer> memo = new HashSet<>();

    // Recursive case: find the minimum cost to reach the top from
    // the first two elements in the cost array, and memoize the solution
    int minCost = Math.min(
        minCostClimbingStairs(Arrays.copyOfRange(cost, 2, cost.length)),
        minCostClimbingStairs(Arrays.copyOfRange(cost, 3, cost.length))
    );
    memo.add(minCost);

    // Return the memoized solution if it exists, otherwise the current cost
    return memo.contains(minCost) ? minCost : cost[0] + cost[1];
}

