public static int findNthUglyNumber(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("The argument 'n' must be non-negative.");
    }
    if (n == 0) {
        return 0;
    }

    int[] factors = new int[] {2, 3, 5};
    PriorityQueue<Long> pq = new PriorityQueue<>();

    for (int factor : factors) {
        pq.offer(1L * factor);
    }

    for (int i = 1; i < n; i++) {
        Long min = pq.poll();
        pq.offer(Math.min(min * factors[0], Math.min(min * factors[1], min * factors[2])));
    }

    return pq.poll().intValue();
}

