return result;

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueElements = new HashSet<>();
    int sum = 0;
    for (int num : nums) {
        if (uniqueElements.add(num)) {
            sum += num;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;

    for (int i = 1; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
            count++;
            if (n / i != i) {
                count++;
            }
        }
    }

    return count;
}

private static String reverseWords(String s) {

        String result = "";
        for(String word : s.split(" ")) {
            char[] letters = word.toCharArray();
            for(int i = 0; i < letters.length; i++) {
                letters[i] = reverseChar(letters[i]);
            }
            result += String.join("", Arrays.asList(letters)) + "";
        }
        return result;
    }

private static char reverseChar(char letter){
        switch(letter) {
            case 'a':
                return 'A';
            case 'b':
                return 'B';
            // ...
            case 'z':
                return 'Z';
            default:
                return Character.toLowerCase(letter);
        }
    }
